export function decodeCases(){
  const cases=[[],[0],[0xef,0xbb,0xbf],[0xe2,0x82],[0xf0,0x9f,0x98,0x80],
    [0xed,0xa0,0x80],[0xe0,0x80,0x80],[0xf4,0x90,0x80,0x80],
    [0xf0,0x90,0x41,0x80],[0xc0,0xaf],[0xc2,0xc2,0xa2]]
  for(let a=0;a<256;a++)for(let b=0;b<256;b++)cases.push([a,b])
  let seed=83
  for(let i=0;i<500;i++){const bytes=[];for(let j=0;j<32;j++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;bytes.push(seed>>>24)}cases.push(bytes)}
  return cases
}
